var lastRule = '';

function FindProxyForURL(url, host) {
    var ret = testURL(url, host);
    if (ret != undefined)
        return ret;
    return direct;
}

function testURL(url, host) {
    for (var i = 0; i < rules.length; i++) {
        for (var j = 0; j < rules[i].length; j++) {
            for (var k = 0; k < rules[i][j].length; k++) {
                lastRule = rules[i][j][k];
                match = regExpMatch(url, lastRule);
                if(match) {
                    if (j == 0)
                        return reject;
                    if (j == 1)
                        return direct;
                    if (j == 2)
                        return proxy;
                }
            }
        }
    }
}

function regExpMatch(url, pattern) {
    try {
        var result = new RegExp(pattern).test(url)
        return result;
    } catch(ex) {
        return false;
    }
}
